-- this chunk exists already (the whole transaction stops); English (media_exercise_sets) is not touched.
begin;
do $g$ begin
  if exists (select 1 from public.media_exercise_sets_l10n where learning_language = 'fr' and media_id in (7369,5502,730,230,7119,4930,5358,7,4360,5379,798,7200,376,5538,5117,6836,5540,5671,124,4364,7453,7883)) then
    raise exception 'A57 out/b002_fr_04.sql: rows exist already - nothing written';
  end if;
