do $g$ begin
  if (select count(*) from public.media_exercise_sets_l10n where learning_language = 'fr' and media_id in (7369,5502,730,230,7119,4930,5358,7,4360,5379,798,7200,376,5538,5117,6836,5540,5671,124,4364,7453,7883)) <> 22 then
    raise exception 'A57 out/b002_fr_04.sql: not 22 rows after the insert';
  end if;
end $g$;
